describe('constants', () => {
  it('PHOTO_MEDIUM is "photograph"', () => {
    expect(PHOTO_MEDIUM).toBe('photograph');
  });

  it('CANONICAL_MEDIUMS contains expected values', () => {
    expect(CANONICAL_MEDIUMS).toContain('photograph');
    expect(CANONICAL_MEDIUMS).toContain('illustration');
    expect(CANONICAL_MEDIUMS).toContain('3d_render');
    expect(CANONICAL_MEDIUMS).toContain('painting');
    expect(CANONICAL_MEDIUMS).toContain('graphic_design');
    expect(CANONICAL_MEDIUMS).toHaveLength(5);
  });

  it('MAX_IMAGE_PALETTE is 16', () => expect(MAX_IMAGE_PALETTE).toBe(16));
  it('MAX_ELEMENT_PALETTE is 5', () => expect(MAX_ELEMENT_PALETTE).toBe(5));
  it('BBOX_MAX is 1000', () => expect(BBOX_MAX).toBe(1000));
});

// ---------------------------------------------------------------------------
// canonMedium
// ---------------------------------------------------------------------------

describe('canonMedium', () => {
  it.each([
    ['photograph', 'photograph'],
    ['photo', 'photograph'],
    ['photography', 'photograph'],
    ['illustration', 'illustration'],
    ['drawing', 'illustration'],
    ['3d', '3d_render'],
    ['3d_render', '3d_render'],
    ['render', '3d_render'],
    ['cgi', '3d_render'],
    ['painting', 'painting'],
    ['oil', 'painting'],
    ['graphic_design', 'graphic_design'],
  ])('maps "%s" → "%s"', (input, expected) => {
    expect(canonMedium(input)).toBe(expected);
  });

  it('handles trailing dot + mixed case', () => {
    expect(canonMedium('Photo.')).toBe('photograph');
    expect(canonMedium('PAINTING.')).toBe('painting');
  });

  it('falls back to PHOTO_MEDIUM for empty string', () => {
    expect(canonMedium('')).toBe(PHOTO_MEDIUM);
  });

  it('passes through unknown mediums as snake_cased', () => {
    expect(canonMedium('digital art')).toBe('digital_art');
  });
});

// ---------------------------------------------------------------------------
// normalizeColor
// ---------------------------------------------------------------------------

describe('normalizeColor', () => {
  it('uppercases valid 6-digit hex', () => {
    expect(normalizeColor('#ff0000')).toBe('#FF0000');
    expect(normalizeColor('aabbcc')).toBe('#AABBCC');
  });

  it('expands 3-digit hex', () => {
    expect(normalizeColor('#abc')).toBe('#AABBCC');
    expect(normalizeColor('#fff')).toBe('#FFFFFF');
    expect(normalizeColor('#000')).toBe('#000000');
    expect(normalizeColor('#f00')).toBe('#FF0000');
  });

  it('returns null for invalid values', () => {
    expect(normalizeColor('red')).toBeNull();
    expect(normalizeColor('#gg0000')).toBeNull();
    expect(normalizeColor(123 as any)).toBeNull();
    expect(normalizeColor(null as any)).toBeNull();
  });
});

// ---------------------------------------------------------------------------
// detect
// ---------------------------------------------------------------------------

describe('detect', () => {
  it('returns true for valid ideogram4 JSON', () => {
    expect(
      detect(JSON.stringify({ compositional_deconstruction: { background: '', elements: [] } })),
    ).toBe(true);
  });

  it('returns false for JSON missing compositional_deconstruction', () => {
    expect(detect(JSON.stringify({ style_description: {} }))).toBe(false);
  });

  it('returns false for non-JSON text', () => {
    expect(detect('a cat sat on a mat')).toBe(false);
    expect(detect('')).toBe(false);
  });

  it('returns false for JSON array', () => {
    expect(detect('[1,2,3]')).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// parse
// ---------------------------------------------------------------------------

describe('parse', () => {
  it('parses plain JSON', () => {
    const raw = JSON.stringify({ foo: 'bar' });
    expect(parse(raw)).toEqual({ foo: 'bar' });
  });

  it('strips ```json fences', () => {
    const raw = '```json\n{"a":1}\n```';
    expect(parse(raw)).toEqual({ a: 1 });
  });

  it('strips ``` fences without language tag', () => {
    const raw = '```\n{"b":2}\n```';
    expect(parse(raw)).toEqual({ b: 2 });
  });

  it('extracts outermost {...} from surrounding prose', () => {
    const raw = 'Here is the JSON: {"c":3} end.';
    expect(parse(raw)).toEqual({ c: 3 });
  });

  it('returns null for empty string', () => {
    expect(parse('')).toBeNull();
  });

  it('returns null for non-JSON text', () => {
    expect(parse('hello world')).toBeNull();
  });

  it('returns null for JSON array', () => {
    expect(parse('[1,2,3]')).toBeNull();
  });
});

// ---------------------------------------------------------------------------
// normalize — photo branch
// ---------------------------------------------------------------------------

describe('normalize — photo branch', () => {
  it('produces photo key order: aesthetics, lighting, photo, medium, color_palette', () => {
    const out = normalize({
      style_description: { medium: 'photograph', photo: 'test' },
      compositional_deconstruction: { background: '', elements: [] },
    });
    const keys = Object.keys(out.style_description);
    expect(keys).toEqual(['aesthetics', 'lighting', 'photo', 'medium', 'color_palette']);
  });

  it('sets photo field from photo key', () => {
    const out = normalize({ style_description: { medium: 'photograph', photo: '35mm' } });
    expect(out.style_description.photo).toBe('35mm');
    expect('art_style' in out.style_description).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// normalize — non-photo branch
// ---------------------------------------------------------------------------

describe('normalize — non-photo branch', () => {
  it('produces art order: aesthetics, lighting, medium, art_style, color_palette', () => {
    const out = normalize({
      style_description: { medium: 'painting', art_style: 'impressionist' },
      compositional_deconstruction: { background: '', elements: [] },
    });
    const keys = Object.keys(out.style_description);
    expect(keys).toEqual(['aesthetics', 'lighting', 'medium', 'art_style', 'color_palette']);
  });

  it('migrates photo→art_style for non-photo medium', () => {
    const out = normalize({
      style_description: { medium: 'painting', photo: 'impressionist' },
      compositional_deconstruction: { background: '', elements: [] },
    });
    expect(out.style_description.art_style).toBe('impressionist');
    expect('photo' in out.style_description).toBe(false);
  });

  it('does not set photo key on non-photo branch', () => {
    const out = normalize({ style_description: { medium: 'illustration', art_style: 'manga' } });
    expect('photo' in out.style_description).toBe(false);
    expect(out.style_description.art_style).toBe('manga');
  });
});

// ---------------------------------------------------------------------------
// normalize — top-level key order
// ---------------------------------------------------------------------------

describe('normalize — top-level key order', () => {
  it('produces high_level_description, style_description, compositional_deconstruction', () => {
    const out = normalize({});
    expect(Object.keys(out)).toEqual([
      'high_level_description',
      'style_description',
      'compositional_deconstruction',
    ]);
  });

  it('fills missing fields with defaults', () => {
    const out = normalize({});
    expect(out.high_level_description).toBe('');
    expect(out.style_description.aesthetics).toBe('');
    expect(out.style_description.medium).toBe(PHOTO_MEDIUM);
    expect(out.compositional_deconstruction.background).toBe('');
    expect(out.compositional_deconstruction.elements).toEqual([]);
  });
});

// ---------------------------------------------------------------------------
// normalize — palette
// ---------------------------------------------------------------------------

describe('normalize — image palette', () => {
  it('caps image palette at 16 and uppercases', () => {
    const d: any = {
      style_description: {
        color_palette: Array.from({ length: 20 }, (_, i) => '#' + i.toString(16).padStart(6, '0')),
      },
      compositional_deconstruction: { background: '', elements: [] },
    };
    const out = normalize(d);
    expect(out.style_description.color_palette).toHaveLength(MAX_IMAGE_PALETTE);
    expect(out.style_description.color_palette.every((c) => c === c.toUpperCase())).toBe(true);
  });

  it('deduplicates palette entries', () => {
    const d: any = {
      style_description: {
        color_palette: ['#ff0000', '#FF0000', '#ff0000'],
      },
      compositional_deconstruction: { background: '', elements: [] },
    };
    const out = normalize(d);
    expect(out.style_description.color_palette).toHaveLength(1);
    expect(out.style_description.color_palette[0]).toBe('#FF0000');
  });

  it('expands 3-digit hex in palette', () => {
    const d: any = {
      style_description: { color_palette: ['#abc'] },
      compositional_deconstruction: { background: '', elements: [] },
    };
    const out = normalize(d);
    expect(out.style_description.color_palette[0]).toBe('#AABBCC');
  });

  it('drops invalid colour strings', () => {
    const d: any = {
      style_description: { color_palette: ['red', 'not-a-hex', '#ff0000'] },
      compositional_deconstruction: { background: '', elements: [] },
    };
    const out = normalize(d);
    expect(out.style_description.color_palette).toEqual(['#FF0000']);
  });
});

describe('normalize — element palette cap', () => {
  it('caps element palette at 5', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [
          {
            type: 'obj',
            desc: 'x',
            color_palette: ['#f00', '#0f0', '#00f', '#ff0', '#0ff', '#f0f'],
          },
        ],
      },
    };
    const out = normalize(d);
    expect(out.compositional_deconstruction.elements[0].color_palette).toHaveLength(
      MAX_ELEMENT_PALETTE,
    );
  });
});

// ---------------------------------------------------------------------------
// normalize — bbox
// ---------------------------------------------------------------------------

describe('normalize — bbox', () => {
  it('clamps bbox values to [0, BBOX_MAX] and rounds', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [{ type: 'obj', bbox: [-10, 500, 1500, 999], desc: '' }],
      },
    };
    const out = normalize(d);
    expect(out.compositional_deconstruction.elements[0].bbox).toEqual([0, 500, 1000, 999]);
  });

  it('drops bbox if not length-4', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [{ type: 'obj', bbox: [1, 2, 3], desc: '' }],
      },
    };
    const out = normalize(d);
    expect('bbox' in out.compositional_deconstruction.elements[0]).toBe(false);
  });

  it('drops bbox if unparseable', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [{ type: 'obj', bbox: [1, 'nan', 3, 4], desc: '' }],
      },
    };
    // 'nan' parseFloat → NaN → isFinite false → drops bbox
    const out = normalize(d);
    expect('bbox' in out.compositional_deconstruction.elements[0]).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// normalize — element type and key order
// ---------------------------------------------------------------------------

describe('normalize — element type and key order', () => {
  it('obj element key order: type, bbox, desc, color_palette', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [{ type: 'obj', bbox: [0, 0, 100, 100], desc: 'thing', color_palette: [] }],
      },
    };
    const out = normalize(d);
    expect(Object.keys(out.compositional_deconstruction.elements[0])).toEqual([
      'type',
      'bbox',
      'desc',
      'color_palette',
    ]);
  });

  it('text element key order: type, bbox, text, desc, color_palette', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [
          { type: 'text', bbox: [0, 0, 50, 20], text: 'Hi', desc: 'label', color_palette: [] },
        ],
      },
    };
    const out = normalize(d);
    expect(Object.keys(out.compositional_deconstruction.elements[0])).toEqual([
      'type',
      'bbox',
      'text',
      'desc',
      'color_palette',
    ]);
  });

  it('unknown type is treated as obj', () => {
    const d: any = {
      compositional_deconstruction: {
        background: '',
        elements: [{ type: 'unknown', desc: 'thing' }],
      },
    };
    const out = normalize(d);
    expect(out.compositional_deconstruction.elements[0].type).toBe('obj');
  });
});

// ---------------------------------------------------------------------------
// serialize
// ---------------------------------------------------------------------------

describe('serialize', () => {
  it('produces compact JSON (no spaces)', () => {
    const doc = normalize({
      high_level_description: 'test',
      style_description: { medium: 'photograph', color_palette: [] },
      compositional_deconstruction: { background: '', elements: [] },
    });
    const s = serialize(doc);
    expect(s).not.toContain(' : ');
    expect(s).not.toContain(', ');
    // Should be parseable
    expect(JSON.parse(s)).toMatchObject({ high_level_description: 'test' });
  });

  it('does not escape non-ASCII characters', () => {
    const doc = normalize({ high_level_description: '日本語' });
    const s = serialize(doc);
    expect(s).toContain('日本語');
    expect(s).not.toContain('\\u');
  });
});

// ---------------------------------------------------------------------------
// skeleton
// ---------------------------------------------------------------------------

describe('skeleton', () => {
  it('wraps text as high_level_description', () => {
    const s = skeleton('a beautiful cat');
    expect(s.high_level_description).toBe('a beautiful cat');
    expect(s.compositional_deconstruction.elements).toEqual([]);
    expect(s.style_description.medium).toBe(PHOTO_MEDIUM);
  });

  it('trims whitespace', () => {
    const s = skeleton('  hello  ');
    expect(s.high_level_description).toBe('hello');
  });

  it('handles empty string', () => {
    const s = skeleton('');
    expect(s.high_level_description).toBe('');
  });

  it('produces a fully normalized doc with correct key order', () => {
    const s = skeleton('test');
    expect(Object.keys(s)).toEqual([
      'high_level_description',
      'style_description',
      'compositional_deconstruction',
    ]);
  });
});

// ---------------------------------------------------------------------------
// Backend parity round-trip tests (CRITICAL GATE)
// ---------------------------------------------------------------------------

describe('backend parity — round-trip serialize(normalize(parse(raw)))', () => {
  it('photo branch matches Python backend output exactly', () => {
    const raw = JSON.stringify(PARITY_PHOTO_INPUT);
    const result = serialize(normalize(parse(raw)!));
    expect(result).toBe(EXPECTED_PHOTO);
  });

  it('non-photo branch with photo→art_style migration matches Python backend exactly', () => {
    const raw = JSON.stringify(PARITY_NON_PHOTO_INPUT);
    const result = serialize(normalize(parse(raw)!));
    expect(result).toBe(EXPECTED_NON_PHOTO);
  });

  it('stress: palette cap 16/5, 3-digit hex, bbox clamp matches Python backend exactly', () => {
    const raw = JSON.stringify(PARITY_STRESS_INPUT);
    const result = serialize(normalize(parse(raw)!));
    expect(result).toBe(EXPECTED_STRESS);
  });

  it('unicode: non-ASCII characters not escaped, matches Python backend exactly', () => {
    const raw = JSON.stringify(PARITY_UNICODE_INPUT);
    const result = serialize(normalize(parse(raw)!));
    expect(result).toBe(EXPECTED_UNICODE);
  });
});
